component.script:
"""Milvus -- store and search embedding vectors in the organization's Milvus.

One node runs one operation, chosen in the Inspector: CREATE_COLLECTION,
INSERT, SEARCH, DELETE, LIST_COLLECTIONS or DROP_COLLECTION. The vectors and
texts come from the incoming request_data, at the paths the Embeddings Field
and Texts Field name (${embeddings} by default). The collection name and filter
expression may contain ${field} placeholders.

A misconfigured node raises ValueError before Milvus is touched, and a Milvus
failure raises from the client. Neither is caught: a vector that was not
stored must fail the run, never be counted as inserted.
"""

import json
import re

import perceivo

# The fields each operation adds to response_data; the artifact carries exactly these.
_RESULT_FIELDS = {
    "CREATE_COLLECTION": ("operation", "collection_name"),
    "INSERT": ("operation", "collection_name", "insert_count", "inserted_ids"),
    "SEARCH": ("operation", "collection_name", "sources", "collection_missing"),
    "DELETE": ("operation", "collection_name", "deleted"),
    "LIST_COLLECTIONS": ("operation", "collection_name", "collections"),
    "DROP_COLLECTION": ("operation", "collection_name"),
}
_METRICS = ("COSINE", "L2", "IP")
_MAX_DIMENSION = 32768
_MAX_TOP_K = 1000
_PLACEHOLDER = re.compile(r"\$\{([\w.]+)\}")
_REFERENCE = re.compile(r"^\$\{([\w.]+)\}$")


def _lookup(data, path: str):
    """Return (True, value) for a dotted path into data, or (False, None)."""
    value = data
    for part in path.split("."):
        if isinstance(value, dict) and part in value:
            value = value[part]
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def _fill(label: str, template: str, data: dict) -> str:
    """Replace each ${path} in template with that value from data, raising on a missing field."""

    def _replace(match):
        found, value = _lookup(data, match.group(1))
        if not found:
            raise ValueError(
                f"{label} refers to ${{{match.group(1)}}}, but the incoming data has no such field."
            )
        return value if isinstance(value, str) else json.dumps(value)

    return _PLACEHOLDER.sub(_replace, template)


def _param(name: str, default: str = "") -> str:
    value = perceivo.params.get(name, default)
    return default if value is None else str(value)


def _bounded_int(name: str, label: str, default: int, low: int, high: int) -> int:
    raw = perceivo.params.get(name, default)
    try:
        number = int(raw)
    except (TypeError, ValueError):
        raise ValueError(f"{label} is {raw!r}. Use a whole number from {low} to {high}.") from None
    if not low <= number <= high:
        raise ValueError(f"{label} is {number}. Use a whole number from {low} to {high}.")
    return number


def _referenced(label: str, reference: str, data: dict, required: bool):
    """The object a whole ${path} parameter points at, or None when optional and absent."""
    match = _REFERENCE.match(reference.strip())
    if not match:
        raise ValueError(f"{label} is {reference!r}. Use a ${{path}} reference into the incoming data.")
    found, value = _lookup(data, match.group(1))
    if not found and required:
        raise ValueError(f"{label} refers to {reference}, but the incoming data has no such field.")
    return value if found else None


def _is_vector(value) -> bool:
    return (
        isinstance(value, list)
        and bool(value)
        and all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in value)
    )


def _vectors(value) -> tuple:
    """Return (vectors, single): one vector is wrapped into a batch of one."""
    if _is_vector(value):
        return [value], True
    if isinstance(value, list) and value and all(_is_vector(v) for v in value):
        return value, False
    raise ValueError("The embeddings must be one vector of numbers, or a list of such vectors.")


def _aligned(name: str, value, count: int, single: bool, kind: type) -> list:
    """A per-vector list for texts or metadata; a lone item is accepted for a single vector."""
    if value is None:
        return [kind() for _ in range(count)]
    if single and isinstance(value, kind):
        value = [value]
    if not isinstance(value, list) or len(value) != count or not all(isinstance(v, kind) for v in value):
        raise ValueError(
            f"{name} must be a list of {count} {kind.__name__} item(s), one per vector, or be left out."
        )
    return value


def _source(hit: dict) -> dict:
    entity = hit.get("entity") or {}
    return {
        "id": hit.get("id"),
        "distance": hit.get("distance"),
        "text": entity.get("text", ""),
        "metadata": entity.get("metadata") or {},
    }


@perceivo.agent
async def milvus_agent(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Run one Milvus operation.

    The JSON artifact carries the operation's result. response_data carries the
    same fields on top of the incoming request_data, less the raw vector
    payloads (embeddings, vectors, query_vectors), so downstream nodes keep
    their context without carrying the vectors on.
    """
    data = input.request_data or {}
    if not isinstance(data, dict):
        raise ValueError(f"request_data must be an object, not {type(data).__name__}.")

    operation = _param("operation", "SEARCH").strip().upper()
    if operation not in _RESULT_FIELDS:
        raise ValueError(f"Operation is {operation!r}. Choose one of: {', '.join(_RESULT_FIELDS)}.")

    collection_name = _fill("Collection Name", _param("collection_name"), data).strip()
    if not collection_name and operation != "LIST_COLLECTIONS":
        raise ValueError(f"Collection Name is empty. {operation} needs the collection to act on.")

    # Everything an operation needs is checked here, before the connection.
    if operation == "CREATE_COLLECTION":
        dimension = _bounded_int("dimension", "Vector Dimension", 1536, 1, _MAX_DIMENSION)
        metric_type = _param("metric_type", "COSINE").strip().upper()
        if metric_type not in _METRICS:
            raise ValueError(f"Distance Metric is {metric_type!r}. Choose one of: {', '.join(_METRICS)}.")
    elif operation in ("INSERT", "SEARCH"):
        embeddings = _referenced("Embeddings Field", _param("embeddings_field", "${embeddings}"), data, True)
        vectors, single = _vectors(embeddings)
    if operation == "INSERT":
        texts = _aligned(
            "texts", _referenced("Texts Field", _param("texts_field", "${texts}"), data, False),
            len(vectors), single, str,
        )
        metadata = _aligned("metadata", data.get("metadata"), len(vectors), single, dict)
        rows = [{"text": text, "metadata": meta} for text, meta in zip(texts, metadata)]
    elif operation == "SEARCH":
        top_k = _bounded_int("top_k", "Top K Results", 10, 1, _MAX_TOP_K)
        filter_expr = _fill("Filter Expression", _param("filter_expr"), data).strip()
    elif operation == "DELETE":
        ids = data.get("ids")
        if ids is not None and (not isinstance(ids, list) or not ids):
            raise ValueError("request_data.ids must be a non-empty list of ids, or be left out.")
        delete_filter = data.get("filter") or _fill("Filter Expression", _param("filter_expr"), data).strip()
        if not ids and not delete_filter:
            raise ValueError("DELETE needs ids or a filter in request_data, or a Filter Expression.")

    # Forward the incoming data, less the raw vectors this node consumes.
    passthrough = dict(data)
    for consumed in ("embeddings", "vectors", "query_vectors"):
        passthrough.pop(consumed, None)

    milvus = await perceivo.cluster.milvus.connect()
    perceivo.log.info(f"Milvus: {operation}", operation=operation, collection_name=collection_name)

    if operation == "CREATE_COLLECTION":
        await milvus.create_collection(name=collection_name, dimension=dimension, metric_type=metric_type)
        result = {**passthrough, "operation": operation, "collection_name": collection_name}
    elif operation == "INSERT":
        returned = await milvus.insert(collection_name=collection_name, vectors=vectors, metadata=rows)
        inserted = [str(i) for i in returned]
        result = {
            **passthrough,
            "operation": operation,
            "collection_name": collection_name,
            "insert_count": len(inserted),
            "inserted_ids": inserted,
        }
    elif operation == "SEARCH":
        hits = await milvus.search(
            collection_name=collection_name,
            query_vectors=vectors,
            top_k=top_k,
            filter_expr=filter_expr or None,
        )
        # The service answers [] only when the collection does not exist.
        per_query = [[_source(hit) for hit in query_hits] for query_hits in hits] or [[] for _ in vectors]
        result = {
            **passthrough,
            "operation": operation,
            "collection_name": collection_name,
            "sources": per_query[0] if single else per_query,
            "collection_missing": not hits,
        }
    elif operation == "DELETE":
        if ids:
            deleted = await milvus.delete(collection_name=collection_name, ids=[str(i) for i in ids])
        else:
            deleted = await milvus.delete(collection_name=collection_name, filter_expr=delete_filter)
        result = {
            **passthrough,
            "operation": operation,
            "collection_name": collection_name,
            "deleted": int(deleted),
        }
    elif operation == "LIST_COLLECTIONS":
        collections = sorted(await milvus.list_collections())
        result = {
            **passthrough,
            "operation": operation,
            "collection_name": collection_name,
            "collections": collections,
        }
    else:
        await milvus.drop_collection(name=collection_name)
        result = {**passthrough, "operation": operation, "collection_name": collection_name}

    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data={field: result[field] for field in _RESULT_FIELDS[operation]},
            mime_type="application/json",
        ),
        response_data=result,
    )
